import { NextResponse } from 'next/server';
import { auth } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export async function POST() {
  const session = await auth();
  if (!session || session.user.role !== 'ADMIN') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
  }

  // Current billing period: first → last day of current month
  const now = new Date();
  const periodStart = new Date(now.getFullYear(), now.getMonth(), 1);
  const periodEnd   = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59, 999);

  // All active non-admin users with their agent assignments
  const users = await prisma.user.findMany({
    where: { role: 'USER', status: 'ACTIVE' },
    include: {
      assignedAgents: {
        include: { agent: true },
      },
    },
  });

  let generated = 0;
  let skipped   = 0;
  const errors: string[] = [];

  for (const user of users) {
    try {
      // Idempotency check — skip if already invoiced this period (unless DRAFT → recalculate)
      // CANCELLED invoices are ignored: treat them as if no invoice exists
      const existing = await prisma.invoice.findFirst({
        where: { userId: user.id, periodStart, status: { not: 'CANCELLED' } },
      });
      if (existing && existing.status !== 'DRAFT') {
        skipped++;
        continue;
      }

      // Build line items
      const lineItems: Array<{
        type:        'SETUP_FEE' | 'MONTHLY_FEE' | 'USAGE_FEE';
        agentId:     string;
        agentName:   string;
        description: string;
        quantity:    number;
        unitPrice:   number;
        total:       number;
      }> = [];

      for (const ua of user.assignedAgents) {
        const agentName = ua.agent.name;
        const agentRetellId = ua.agent.retellAgentId;

        // SETUP_FEE — one-time, only if not already included in a prior invoice
        // (check invoice_line_items, NOT setupFeePaid — setupFeePaid is only set when PAID)
        if (ua.setupFee) {
          const alreadyBilled = await prisma.invoiceLineItem.findFirst({
            where: {
              type:    'SETUP_FEE',
              agentId: agentRetellId,
              invoice: { userId: user.id, status: { not: 'CANCELLED' } },
            },
          });
          if (!alreadyBilled) {
            const fee = Number(ua.setupFee);
            lineItems.push({
              type:        'SETUP_FEE',
              agentId:     agentRetellId,
              agentName,
              description: `Setup fee — ${agentName}`,
              quantity:    1,
              unitPrice:   fee,
              total:       fee,
            });
          }
        }

        // MONTHLY_FEE
        if (ua.monthlyFee) {
          const fee = Number(ua.monthlyFee);
          lineItems.push({
            type:        'MONTHLY_FEE',
            agentId:     agentRetellId,
            agentName,
            description: `Monthly service fee — ${agentName}`,
            quantity:    1,
            unitPrice:   fee,
            total:       fee,
          });
        }

        // USAGE_FEE — sum call durations in this period
        if (ua.customPrice) {
          const ratePerMin = Number(ua.customPrice);
          const usage = await prisma.call.aggregate({
            where: {
              agentId:        agentRetellId,
              startTimestamp: { gte: ua.assignedAt > periodStart ? ua.assignedAt : periodStart, lte: periodEnd },
              durationMs:     { not: null },
            },
            _sum: { durationMs: true },
          });
          const totalMs  = usage._sum.durationMs ?? 0;
          const minutes  = totalMs / 60000;
          if (minutes > 0) {
            const total = Math.round(minutes * ratePerMin * 100) / 100;
            lineItems.push({
              type:        'USAGE_FEE',
              agentId:     agentRetellId,
              agentName,
              description: `Usage — ${agentName} (${minutes.toFixed(4)} min)`,
              quantity:    Math.round(minutes * 10000) / 10000,
              unitPrice:   ratePerMin,
              total,
            });
          }
        }
      }

      // Skip users with no billable items
      if (lineItems.length === 0) {
        skipped++;
        continue;
      }

      const subtotal = Math.round(lineItems.reduce((s, l) => s + l.total, 0) * 100) / 100;

      if (existing) {
        // DRAFT invoice exists — recalculate USAGE_FEE line items and update totals
        await prisma.$transaction(async tx => {
          await tx.invoiceLineItem.deleteMany({
            where: { invoiceId: existing.id, type: 'USAGE_FEE' },
          });
          const usageItems = lineItems.filter(l => l.type === 'USAGE_FEE');
          if (usageItems.length > 0) {
            await tx.invoiceLineItem.createMany({
              data: usageItems.map(item => ({
                invoiceId:   existing.id,
                type:        item.type,
                agentId:     item.agentId,
                agentName:   item.agentName,
                description: item.description,
                quantity:    item.quantity,
                unitPrice:   item.unitPrice,
                total:       item.total,
              })),
            });
          }
          await tx.invoice.update({
            where: { id: existing.id },
            data:  { subtotal, total: subtotal },
          });
        });
      } else {
        const yyyymm = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}`;
        const baseNumber = `INV-${yyyymm}-${user.id.slice(0, 6).toUpperCase()}`;
        // Ensure uniqueness — a cancelled invoice may already hold the base number
        let invoiceNumber = baseNumber;
        let suffix = 2;
        while (await prisma.invoice.findUnique({ where: { invoiceNumber } })) {
          invoiceNumber = `${baseNumber}-${suffix++}`;
        }

        // Create invoice + line items in one transaction
        await prisma.$transaction(async tx => {
          const invoice = await tx.invoice.create({
            data: {
              invoiceNumber,
              userId:          user.id,
              periodStart,
              periodEnd,
              status:          'DRAFT',
              subtotal,
              total:           subtotal,
              isAutoGenerated: false,
            },
          });

          await tx.invoiceLineItem.createMany({
            data: lineItems.map(item => ({
              invoiceId:   invoice.id,
              type:        item.type,
              agentId:     item.agentId,
              agentName:   item.agentName,
              description: item.description,
              quantity:    item.quantity,
              unitPrice:   item.unitPrice,
              total:       item.total,
            })),
          });
          // NOTE: setupFeePaid is NOT set here — it is only set when the invoice is marked PAID
        });
      }

      generated++;
    } catch (err) {
      errors.push(`User ${user.id}: ${err instanceof Error ? err.message : 'Unknown error'}`);
    }
  }

  return NextResponse.json({ generated, skipped, errors });
}
